function decodeBase64(value) {
  const binary = atob(value);
  const bytes = new Uint8Array(binary.length);
  for (let index = 0; index < binary.length; index += 1) {
    bytes[index] = binary.charCodeAt(index);
  }
  return bytes;
}

function cacheHeader(pathname) {
  if (pathname === 'index.html') return 'no-store';
  return 'public, max-age=31536000, immutable';
}

export default {
  async fetch(request) {
    const url = new URL(request.url);
    let pathname = decodeURIComponent(url.pathname).replace(/^\/+/, '');
    if (!pathname) pathname = 'index.html';
    let file = FILES[pathname];
    if (!file && !pathname.includes('.')) file = FILES['index.html'];
    if (!file) return new Response('Not found', { status: 404 });
    return new Response(decodeBase64(file.body), {
      headers: {
        'content-type': file.type,
        'cache-control': cacheHeader(pathname),
      },
    });
  },
};
